import sys
from collections import deque

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
A = tuple(int(x) for x in data[2:2 + n * m])
B = tuple(int(x) for x in data[2 + n * m:2 + 2 * n * m])
ops = []
for k in range(2, min(n, m) + 1):
    for r in range(n - k + 1):
        for c in range(m - k + 1):
            perm = list(range(n * m))
            for a in range(k):
                for b in range(k):
                    perm[(r + a) * m + c + b] = (r + b) * m + c + a
            ops.append(perm)
seen = {A}
dq = deque([A])
while dq:
    cur = dq.popleft()
    for p in ops:
        nxt = tuple(cur[p[i]] for i in range(n * m))
        if nxt not in seen:
            seen.add(nxt)
            dq.append(nxt)
print("YES" if B in seen else "NO")

